using EnterpriseDocumentIntelligence.BuildingBlocks.Infrastructure;using EnterpriseDocumentIntelligence.BuildingBlocks.Security;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
public sealed record AuditRequest(string Action,string ResourceType,Guid? ResourceId,string Outcome,string? MetadataJson);
[ApiController,Route("api/v1/audit"),Authorize(Roles=Roles.Administrator)]public sealed class AuditController(DocumentDbContext db,ICurrentUser user,ILogger<AuditController> log):ControllerBase{[HttpPost]public async Task<IActionResult>Record(AuditRequest r,CancellationToken ct){var e=AuditRules.Create(new AuditCommand(user.TenantId,user.UserId,r.Action,r.ResourceType,r.ResourceId,r.Outcome,user.CorrelationId,r.MetadataJson));db.AuditEvents.Add(e);await db.SaveChangesAsync(ct);log.LogInformation("AuditEvent {EventId} Action={Action} Tenant={TenantId}",e.Id,e.Action,user.TenantId);return Accepted(new{id=e.Id});}[HttpGet]public async Task<IActionResult>Get(DateTimeOffset?from,CancellationToken ct){var q=db.AuditEvents.AsNoTracking().Where(x=>x.TenantId==user.TenantId);if(from.HasValue)q=q.Where(x=>x.CreatedAt>=from.Value);return Ok(await q.OrderByDescending(x=>x.CreatedAt).Take(500).ToListAsync(ct));}}